diff --git a/src/tools/diff-limits.ts b/src/tools/diff-limits.ts
--- a/src/tools/diff-limits.ts
+++ b/src/tools/diff-limits.ts
@@ -12,7 +12,7 @@ export interface Limits { files: number; lines: number }
 /** Reasons the diff is over limits; empty means within limits. At most `limits.files` files may change. */
 export function overLimits(changedFiles: string[], addedLines: number, limits: Limits): string[] {
   const reasons: string[] = [];
-  if (changedFiles.length > limits.files) reasons.push(`${changedFiles.length} files, limit ${limits.files}`);
+  if (changedFiles.length >= limits.files) reasons.push(`${changedFiles.length} files, limit ${limits.files}`);
   if (addedLines > limits.lines) reasons.push(`${addedLines} lines, limit ${limits.lines}`);
   return reasons;
 }
diff --git a/tests/unit/tools/diff-limits.test.ts b/tests/unit/tools/diff-limits.test.ts
--- a/tests/unit/tools/diff-limits.test.ts
+++ b/tests/unit/tools/diff-limits.test.ts
@@ -4,4 +4,7 @@ describe("overLimits", () => {
   it("flags a diff over the file limit", () => {
     expect(overLimits(["a", "b", "c", "d", "e", "f"], 1, { files: 5, lines: 100 })).toHaveLength(1);
   });
+  it("is quiet well under the limit", () => {
+    expect(overLimits(["a"], 1, { files: 5, lines: 100 })).toEqual([]);
+  });
 });
